def watermark_existing(apps, schema_editor):
    """Photos uploaded before watermarks: keep the file as the original, show a watermarked copy (logo + the IG name
    from the shop info, if set). Uses the historical models, so later model changes can't break this step."""
    from menu.watermark import handle_from_url, render

    Shop = apps.get_model("menu", "ShopInfo")
    shop = Shop.objects.first()
    handle = handle_from_url(getattr(shop, "instagram_url", "") or "")
    for g in apps.get_model("menu", "GalleryPhoto").objects.exclude(image="").filter(video="", original=""):
        try:
            with g.image.open("rb") as f:
                data = f.read()
            old = g.image.name
            g.original.save("photo.jpg", ContentFile(data), save=False)
            with g.original.open("rb") as f:
                g.image.save("photo.jpg", render(f, handle), save=False)
            g.save(update_fields=["original", "image"])
            g.image.storage.delete(old)
        except (OSError, ValueError):  # a missing/broken file: leave that photo as it was
            continue


